function fibonacci($n) {
    $a = 0;
    $b = 1;
    for ($i = 0; $i < $n; $i++) {
        yield $a;
        $temp = $a;
        $a = $b;
        $b = $temp + $b;
    }
}

function filterGenerator($gen, $filter) {
    foreach ($gen as $value) {
        if ($filter($value)) {
            yield $value;
        }
    }
}

$fib = fibonacci(15);
$evenFib = filterGenerator($fib, fn($x) => $x % 2 == 0);
