class ValidationException extends Exception {}
class DatabaseException extends Exception {}
class NetworkException extends Exception {}

function processData($data) {
    if (empty($data)) {
        throw new ValidationException("Data cannot be empty");
    }
    if (!is_array($data)) {
        throw new ValidationException("Data must be an array");
    }
    return array_sum($data);
}

function handleErrors($callback, $data) {
    try {
        return $callback($data);
    } catch (ValidationException $e) {
        return "VALIDATION_ERROR: " . $e->getMessage();
    } catch (DatabaseException $e) {
        return "DATABASE_ERROR: " . $e->getMessage();
    } catch (Exception $e) {
        return "UNKNOWN_ERROR: " . $e->getMessage();
    } finally {
        // Cleanup
    }
}

