declare(strict_types=1);

function test(int $i, string $s, bool $b) {
    return "$i,$s,$b";
}

echo test(42, 'hello', true);

function test(): string {
    return 'hello';
}

echo test();

function test(?int $i): ?string {
    if ($i === null) return null;
    return (string)$i;
}

echo test(42) . ',' . (test(null) === null ? 'null' : 'not-null');

function test(int|string $value): string {
    return (string)$value;
}

echo test(42) . ',' . test('hello');

