$arr = [1, 2, 3, 4, 5];
echo 'count:' . count($arr) . "\n";
echo 'sum:' . array_sum($arr) . "\n";
echo 'product:' . array_product($arr) . "\n";
echo 'max:' . max($arr) . "\n";
echo 'min:' . min($arr) . "\n";

$arr = [1, 2, 3, 4, 5];
$mapped = array_map(fn($x) => $x * 2, $arr);
echo 'mapped:' . implode(',', $mapped) . "\n";

$filtered = array_filter($arr, fn($x) => $x > 2);
echo 'filtered:' . implode(',', $filtered) . "\n";

$reduced = array_reduce($arr, fn($carry, $item) => $carry + $item, 0);
echo 'reduced:' . $reduced;

